#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# harmflow.com → GitHub Pages (harmflow/harmflow-site), at GoDaddy.
#
# Usage: scripts/dns-cutover-wizard.sh
#
# Points the domain at GitHub Pages and enforces HTTPS, checking every record on
# GoDaddy's own name server. Safe to re-run: a stage already done passes its
# check at once. It remembers the TXT value between runs and appends every
# check's output, with its date, to an evidence file. Both live outside the
# repository, since the evidence is not committed.

STATE_DIR="${XDG_STATE_HOME:-$HOME/.local/state}/harmflow-site"
mkdir -p "$STATE_DIR"
ENV_FILE="${ENV_FILE:-$STATE_DIR/dns-cutover.env}"
EVIDENCE="$STATE_DIR/dns-cutover-evidence.txt"

DOMAIN="harmflow.com"
ORG="harmflow"
REPO="harmflow/harmflow-site"
NS="ns57.domaincontrol.com"   # GoDaddy's authoritative server: no cache to wait out
CHALLENGE="_github-pages-challenge-$ORG.$DOMAIN"
PAGES_A="185.199.108.153 185.199.109.153 185.199.110.153 185.199.111.153"
PAGES_AAAA="2606:50c0:8000::153 2606:50c0:8001::153 2606:50c0:8002::153 2606:50c0:8003::153"
PARKED_A="3.33.130.190 15.197.148.33"
GODADDY_DNS="https://dcc.godaddy.com/control/portfolio/$DOMAIN/settings?tab=dns"
PAGES_SETTINGS="https://github.com/$REPO/settings/pages"

# sorted_answers TYPE NAME: the authoritative answers, one per line, sorted.
sorted_answers() { dig +short "@$NS" "$2" "$1" | sed 's/\.$//; s/"//g' | sort; }

# evidence "title" CMD...: runs CMD, shows it, and appends it to the evidence file.
evidence() {
  local title="$1"; shift
  { printf '\n## %s — %s\n$ %s\n' "$title" "$(date '+%Y-%m-%d %H:%M %z')" "$*"; "$@" 2>&1 || true; } \
    | tee -a "$EVIDENCE" | sed 's/^/    /'
}

# wait_until "what" CHECK...: re-runs CHECK on Enter until it succeeds, or the human skips.
wait_until() {
  local what="$1"; shift
  until "$@"; do
    warn "not yet: $what"
    confirm "Check again? (No skips this check)" || { SKIPPED+=("$what"); return 0; }
  done
  printf '  %s✓ %s%s\n' "$GREEN" "$what" "$RESET"
}

# pages_health: GitHub's DNS check of the domain. The API answers 202 with nothing while it computes, so ask again.
pages_health() {
  local i out
  for i in 1 2 3 4 5 6; do
    out=$(gh api "repos/$REPO/pages/health" -q '.domain // empty | {is_valid, is_pointed_to_github_pages_server, is_https_eligible}' 2>/dev/null || true)
    [[ -n "$out" ]] && { printf '%s\n' "$out"; return 0; }
    sleep 5
  done
  printf 'GitHub is still computing the check; the Pages settings page shows its result.\n'
}

cert_domains()  { gh api "repos/$REPO/pages" -q '(.https_certificate.domains // []) | join(" ")' 2>/dev/null || true; }
has_challenge() { [[ -n "${PAGES_TXT:-}" ]] && sorted_answers TXT "$CHALLENGE" | grep -qxF "$PAGES_TXT"; }
no_parked()     { local a; a=$(sorted_answers A "$DOMAIN"); for ip in $PARKED_A; do grep -qxF "$ip" <<<"$a" && return 1; done; return 0; }
pages_a()       { [[ "$(sorted_answers A "$DOMAIN" | tr '\n' ' ')" == "$(tr ' ' '\n' <<<"$PAGES_A" | sort | tr '\n' ' ')" ]]; }
pages_aaaa()    { [[ "$(sorted_answers AAAA "$DOMAIN" | tr '\n' ' ')" == "$(tr ' ' '\n' <<<"$PAGES_AAAA" | sort | tr '\n' ' ')" ]]; }
www_cname()     { [[ "$(sorted_answers CNAME "www.$DOMAIN")" == "$ORG.github.io" ]]; }
cert_approved() { [[ "$(gh api "repos/$REPO/pages" -q '.https_certificate.state // ""' 2>/dev/null)" == "approved" ]]; }
cert_has_www()  { grep -qw "www.$DOMAIN" <<<"$(cert_domains)"; }
https_on()      { [[ "$(gh api "repos/$REPO/pages" -q '.https_enforced' 2>/dev/null)" == "true" ]]; }

TOTAL_STAGES=8

banner "harmflow.com → GitHub Pages, at GoDaddy"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "GitHub: start verifying $DOMAIN for the $ORG organization"
say "Verifying the domain keeps any other GitHub account from taking it over."
open_url "https://github.com/organizations/$ORG/settings/pages"
step "Click 'Add a domain', type $DOMAIN, and click 'Add domain'."
step "Under 'Add a DNS TXT record', copy the TXT record's value (leave the page open)."
note "Already added? Use the ⋯ next to the domain → 'Continue verifying' to see the value."
note "Already verified? Paste the value the TXT record holds, or press Enter to keep the saved one."
ask PAGES_TXT "Paste the TXT value:"
write_env PAGES_TXT "$PAGES_TXT"
pause

# ── 2 ────────────────────────────────────────────────────────────────────
stage "GoDaddy: add the TXT record, then verify on GitHub"
open_url "$GODADDY_DNS"
note "If the link does not land on the DNS records: My Products → $DOMAIN → DNS."
step "Add a record → Type: TXT"
step "Name: _github-pages-challenge-$ORG   (GoDaddy adds .$DOMAIN itself)"
step "Value: $PAGES_TXT"
step "TTL: the default. Save."
pause "Saved? Press Enter to check it on GoDaddy's name server"
wait_until "the TXT record answers on $NS" has_challenge
evidence "Verification TXT" dig +short "@$NS" "$CHALLENGE" TXT
step "Back on GitHub's Pages settings, click 'Verify'. Keep the TXT record for good."
pause "Verified? Press Enter"

# ── 3 ────────────────────────────────────────────────────────────────────
# www goes first: GitHub requests one certificate once the apex points to it, and covers www only if www already does.
stage "GoDaddy: point www to $ORG.github.io"
open_url "$GODADDY_DNS"
step "Edit the CNAME record named www (GoDaddy's default points it to $DOMAIN)."
step "Value: $ORG.github.io   (no repository name). Save."
note "GitHub Pages then sends www.$DOMAIN to $DOMAIN."
pause "Saved? Press Enter to check"
wait_until "www.$DOMAIN is a CNAME for $ORG.github.io" www_cname
evidence "www CNAME" dig +short "@$NS" "www.$DOMAIN" CNAME

# ── 4 ────────────────────────────────────────────────────────────────────
stage "GoDaddy: remove the parking records and any forwarding"
warn "From here until stage 5 is saved, $DOMAIN answers nothing. Do stages 4 and 5 together."
open_url "$GODADDY_DNS"
step "Delete every A record named @ whose value is 3.33.130.190 or 15.197.148.33"
note "  (GoDaddy may show it as 'Parked' or 'WebsiteBuilder Site')."
step "If the domain has Forwarding set (the Forwarding section of the same page), delete it."
step "Delete any record named * (a wildcard): it lets another site claim a subdomain."
if no_parked; then
  note "No parking address answers any more."
elif confirm "Have you deleted the parking records?"; then
  wait_until "no parking address answers for $DOMAIN" no_parked
else
  SKIPPED+=("remove the parking A records at GoDaddy")
fi

# ── 5 ────────────────────────────────────────────────────────────────────
stage "GoDaddy: point $DOMAIN to GitHub Pages"
open_url "$GODADDY_DNS"
say "Add eight records, all named @, TTL the default:"
for ip in $PAGES_A;    do step "Type A     · Name @ · Value $ip"; done
for ip in $PAGES_AAAA; do step "Type AAAA  · Name @ · Value $ip"; done
pause "All eight saved? Press Enter to check"
wait_until "the four A records are GitHub Pages' and nothing else" pages_a
wait_until "the four AAAA records are GitHub Pages' and nothing else" pages_aaaa
evidence "Apex A" dig +short "@$NS" "$DOMAIN" A
evidence "Apex AAAA" dig +short "@$NS" "$DOMAIN" AAAA

# ── 6 ────────────────────────────────────────────────────────────────────
stage "GitHub Pages: wait for the DNS check and the certificate"
say "GitHub checks the DNS and requests the certificate itself. It usually takes"
say "under an hour, at most 24; you can stop now (Ctrl-C) and re-run the wizard later."
open_url "$PAGES_SETTINGS"
note "The custom domain must read $DOMAIN, with 'DNS check successful'."
evidence "Pages DNS health" pages_health
wait_until "GitHub Pages' certificate for $DOMAIN is approved" cert_approved

# ── 7 ────────────────────────────────────────────────────────────────────
stage "GitHub Pages: a certificate that covers www.$DOMAIN"
if cert_has_www; then
  note "The certificate covers: $(cert_domains)"
else
  warn "The certificate covers only: $(cert_domains). https://www.$DOMAIN fails until it covers www too."
  say "GitHub requests a new certificate when the custom domain is saved again,"
  say "and the site answers a 404 for the minute in between."
  if confirm "Re-save the custom domain now?"; then
    open_url "$PAGES_SETTINGS"
    step "Under 'Custom domain', click 'Remove'."
    step "Type $DOMAIN in the same field and click 'Save'. Wait for 'DNS check successful'."
    pause "Saved again? Press Enter to check the new certificate"
    wait_until "the certificate covers www.$DOMAIN" cert_has_www
  else
    SKIPPED+=("re-save the custom domain so the certificate covers www.$DOMAIN")
  fi
fi

# ── 8 ────────────────────────────────────────────────────────────────────
stage "GitHub Pages: enforce HTTPS"
if https_on; then
  note "HTTPS is already enforced."
elif confirm "Enforce HTTPS for $REPO now? (http:// then redirects to https://)"; then
  if gh api -X PUT "repos/$REPO/pages" -F https_enforced=true >/dev/null 2>&1; then
    printf '  %s✓ HTTPS enforced%s\n' "$GREEN" "$RESET"
  else
    warn "the API refused; tick 'Enforce HTTPS' on the page that opens"
    open_url "$PAGES_SETTINGS"
    pause "Ticked? Press Enter"
  fi
else
  SKIPPED+=("enforce HTTPS in $REPO's Pages settings")
fi
wait_until "HTTPS is enforced" https_on
say "The published site, as a visitor gets it:"
evidence "http:// redirects" curl -sSI "http://$DOMAIN/"
evidence "https:// answers" curl -sSI "https://$DOMAIN/"
evidence "www redirects" curl -sSI "https://www.$DOMAIN/"
evidence "Pages settings" gh api "repos/$REPO/pages" -q '{cname, https_enforced, cert: .https_certificate.state, domains: .https_certificate.domains}'
note "Evidence appended to $EVIDENCE"
pause

finish
